python - <<'PY'
from rcb_client import Robot
import numpy as np
from PIL import Image
from scipy.ndimage import label,find_objects
r=Robot();o=r.get_obs(cameras=['topview','front','left','right'],include_depth=True,video='both')
for k,a in o.last.items(): Image.fromarray(a).save('/app/output/contact2_'+k+'.png')
print('state',o.meta['proprio']['now'][:7])
for k in ['topview','front']:
 d=o.depth[k][0];a=o.last[k];
 for roi_name,roi in [('all',np.ones(d.shape,bool))]:
  m=(d>0.1)&(d<1.485)&(a[:,:,0].astype(int)-a[:,:,1].astype(int)<48)
  L,n=label(m);cs=[]
  for i,s in enumerate(find_objects(L),1):
   if s is None:continue
   y,x=np.where(L[s]==i);N=len(x);y+=s[0].start;x+=s[1].start
   if 8<=N<=1500:cs.append((N,(int(x.min()),int(y.min()),int(x.max()),int(y.max())),a[y,x].mean(axis=0).round(1).tolist(),round(float(np.median(d[y,x])),3)))
  print(k,'comps',sorted(cs,reverse=True)[:12])
PY

